import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Grounded answers with Ollama","description":"","frontmatter":{},"headers":[],"relativePath":"searchable/asking.md","filePath":"searchable/asking.md","lastUpdated":1792947882000}'),i={name:"searchable/asking.md"};function l(o,e,r,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="grounded-answers-with-ollama" tabindex="-1">Grounded answers with Ollama <a class="header-anchor" href="#grounded-answers-with-ollama" aria-label="Permalink to &quot;Grounded answers with Ollama&quot;">​</a></h1><p><code>web_ask</code> selects relevant canonical stash records, builds a bounded prompt, and calls the configured Ollama <code>/api/generate</code> endpoint. Neottia reads the newline-delimited JSON response as it arrives. It bounds each incomplete frame and the cumulative answer, rejects malformed data immediately, and requires one terminal frame before returning <code>answer</code> and <code>contextUrls</code>.</p><p>Start Ollama and make the configured model available:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3</span></span></code></pre></div><p>The default endpoint is <code>http://localhost:11434</code> and the default model is <code>llama3</code>. This local endpoint is the only intentional exception to the public-network destination policy.</p><p>Searchable labels page excerpts as untrusted source material and instructs the model not to follow commands inside them. <code>ask.context_bytes</code> caps the complete UTF-8 prompt, including instructions, question, delimiters, URLs, titles, and content. Pages are added deterministically until the limit is reached.</p><p>No stash match returns <code>NO_RELEVANT_CONTEXT</code> without contacting Ollama. An unreachable model, a deadline, an oversized response, malformed stream frames, data after the terminal frame, or a missing terminal frame also returns a stable error. Neottia closes the HTTP response as soon as stream validation fails. Model answers may still be wrong. Use <code>contextUrls</code> to check important claims.</p>`,7)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
